/**
 * Error types raised by Server Actions that are *expected* failures rather
 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
 * the `AppErrorShape` the client form layer renders, mirroring the convention
 * already used by `PermissionDeniedError` and `TenantScopeError`.
 *
 * These live in `src/actions/_lib` because only the action layer produces
 * them — services throw their own domain errors, and repositories throw none.
 */

import type { LimitedResource } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { PermissionAction } from "@/types/permission";

/** No session at all, or a session whose active organization is gone. */
export class UnauthorizedActionError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedActionError";
  }
}

/**
 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 * `assertCan()` inside services) only in that the action layer already knows
 * the action name and does not need the full `PermissionDecision`.
 */
export class ForbiddenActionError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly action: PermissionAction) {
    super(`Permission denied: ${action}`);
    this.name = "ForbiddenActionError";
  }
}

/** A plan quota from `@/config/plan-limits` would be breached. */
export class PlanLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly resource: LimitedResource,
    readonly limit: number,
    readonly used: number,
  ) {
    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
    this.name = "PlanLimitError";
  }
}

/** The token bucket in `@/lib/rate-limit` refused the request. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** A feature flag that gates the whole action is off for this organization. */
export class FeatureUnavailableError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: string) {
    super(`Feature not available: ${flag}`);
    this.name = "FeatureUnavailableError";
  }
}

/** The row the action addresses does not exist inside the actor's tenant. */
export class ActionNotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(readonly what: string) {
    super(`Not found: ${what}`);
    this.name = "ActionNotFoundError";
  }
}
/**
 * Label rows and the issue↔label join table.
 */
import { and, asc, eq, inArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueLabels, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toLabel } from "./_mappers";
import type { CreateLabelInput, UpdateLabelInput } from "@/schemas/label";
import type { IssueId, LabelId, OrgId } from "@/types/common";
import type { IssueLabel } from "@/types/issue";

export async function listLabels(
  orgId: OrgId,
): Promise<readonly IssueLabel[]> {
  const rows = getDb()
    .select()
    .from(labels)
    .where(orgPredicate(labels.orgId, orgId))
    .orderBy(asc(labels.name))
    .all();
  return rows.map(toLabel);
}

export async function insertLabel(
  input: CreateLabelInput,
): Promise<IssueLabel> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(labels)
    .values({
      id: newId(),
      orgId: input.orgId,
      name: input.name,
      color: input.color,
      description: input.description,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toLabel(row);
}

export async function updateLabel(
  input: UpdateLabelInput,
): Promise<IssueLabel> {
  const row = getDb()
    .update(labels)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
      ...(input.color === undefined ? {} : { color: input.color }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(labels.orgId, input.orgId), eq(labels.id, input.labelId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Label ${input.labelId} not found`);
  return toLabel(row);
}

/** Labels are hard deleted; the join rows go with them. */
export async function deleteLabel(
  orgId: OrgId,
  labelId: LabelId,
): Promise<void> {
  const db = getDb();
  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, labelId),
      ),
    )
    .run();
  db.delete(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, labelId)))
    .run();
}

/** Replaces the whole label set of one issue in a single round trip. */
export async function setIssueLabels(
  orgId: OrgId,
  issueId: IssueId,
  labelIds: readonly LabelId[],
): Promise<void> {
  const db = getDb();
  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.issueId, issueId),
      ),
    )
    .run();

  if (labelIds.length === 0) return;

  db.insert(issueLabels)
    .values(labelIds.map((labelId) => ({ orgId, issueId, labelId })))
    .run();
}

/** Batched lookup keyed by issue id, so list views avoid an N+1. */
export async function listLabelsForIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<Readonly<Record<string, readonly IssueLabel[]>>> {
  if (issueIds.length === 0) return {};

  const rows = getDb()
    .select({ issueId: issueLabels.issueId, label: labels })
    .from(issueLabels)
    .innerJoin(labels, eq(labels.id, issueLabels.labelId))
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(issueLabels.issueId, [...issueIds]),
      ),
    )
    .all();

  const grouped: Record<string, IssueLabel[]> = {};
  for (const row of rows) {
    (grouped[row.issueId] ??= []).push(toLabel(row.label));
  }
  return grouped;
}
/**
 * Membership rows. Every read is filtered by `orgId`; removal is a soft delete.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, count, desc, eq, isNull, like, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { getDb, members, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toMember, toUser } from "./_mappers";
import type { ListMembersInput } from "@/schemas/member";
import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Member, MemberWithUser, Role } from "@/types/member";

/**
 * A removed member is archived, never deleted, and no read ever surfaces one:
 * the scope is fixed here rather than threaded through every call site.
 */
const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};

function liveMemberPredicate() {
  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
}

export async function findMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

export async function findMemberById(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .get();
  return row ? toMember(row) : null;
}

/** Cursor-paged member list joined with the user record the UI renders. */
export async function listMembers(
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  const db = getDb();
  const sort = { sortColumn: members.createdAt, idColumn: members.id };

  const filters = compact(
    orgPredicate(members.orgId, input.orgId),
    liveMemberPredicate(),
    input.role === undefined ? undefined : eq(members.role, input.role),
    input.status === undefined ? undefined : eq(members.status, input.status),
    input.query === undefined
      ? undefined
      : or(
          like(users.name, `%${input.query}%`),
          like(users.email, `%${input.query}%`),
        ),
  );

  const total = db
    .select({ value: count() })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters))
    .get();

  const rows = db
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(members.createdAt), desc(members.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
  );
}

/** The seat count every plan check compares against. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

export async function updateMemberRole(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/** Removal is a soft delete so the audit log keeps pointing at a real row. */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ ...archivePatch(), status: "suspended" })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .run();
}
/**
 * Global user rows. The only repository that is NOT tenant scoped — users exist across organizations.
 */
import { eq, inArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUser } from "./_mappers";
import type { UpdateProfileInput } from "@/schemas/member";
import type { UserId } from "@/types/common";
import type { User } from "@/types/member";

export async function findUserById(userId: UserId): Promise<User | null> {
  const rows = getDb().select().from(users).where(eq(users.id, userId)).all();
  const row = rows.at(0);
  return row ? toUser(row) : null;
}

export async function findUserByEmail(email: string): Promise<User | null> {
  const rows = getDb()
    .select()
    .from(users)
    .where(eq(users.email, email.toLowerCase()))
    .all();
  const row = rows.at(0);
  return row ? toUser(row) : null;
}

export async function insertUser(input: {
  email: string;
  name: string;
  passwordHash: string;
}): Promise<User> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(users)
    .values({
      id: newId(),
      email: input.email.toLowerCase(),
      name: input.name,
      passwordHash: input.passwordHash,
      avatarUrl: null,
      timezone: "UTC",
      emailVerifiedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toUser(row);
}

export async function updateUser(
  userId: UserId,
  patch: UpdateProfileInput,
): Promise<User> {
  const row = getDb()
    .update(users)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.avatarUrl === undefined ? {} : { avatarUrl: patch.avatarUrl }),
      ...(patch.timezone === undefined ? {} : { timezone: patch.timezone }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(users.id, userId))
    .returning()
    .get();

  if (!row) throw new Error(`User ${userId} not found`);
  return toUser(row);
}

/**
 * The password hash never travels on the `User` domain type — nothing outside
 * `AuthService` may see it — so login reads it through this narrow accessor.
 *
 * Not in the manifest: added because `User` deliberately omits the column and
 * credential login has no other way to reach it.
 */
export async function findPasswordHash(
  userId: UserId,
): Promise<string | null> {
  const row = getDb()
    .select({ passwordHash: users.passwordHash })
    .from(users)
    .where(eq(users.id, userId))
    .get();
  return row?.passwordHash ?? null;
}

/** Counterpart of `findPasswordHash`, used by the password-reset flow. */
export async function updatePasswordHash(
  userId: UserId,
  passwordHash: string,
): Promise<void> {
  getDb()
    .update(users)
    .set({ passwordHash, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(users.id, userId))
    .run();
}

/** Batch fetch used by every list view that decorates rows with their author. */
export async function findUsersByIds(
  userIds: readonly UserId[],
): Promise<readonly User[]> {
  if (userIds.length === 0) return [];
  const rows = getDb()
    .select()
    .from(users)
    .where(inArray(users.id, [...userIds]))
    .all();
  return rows.map(toUser);
}
import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const members = sqliteTable(
  "members",
  {
    id: idColumn(),
    ...tenantColumns,
    userId: text("user_id").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    status: text("status", { enum: ["active", "invited", "suspended"] })
      .notNull()
      .default("active"),
    invitedBy: text("invited_by"),
    joinedAt: text("joined_at"),
    lastSeenAt: text("last_seen_at"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("members_org_user_idx").on(table.orgId, table.userId),
    index("members_org_role_idx").on(table.orgId, table.role),
  ],
);

export const invitations = sqliteTable(
  "invitations",
  {
    id: idColumn(),
    ...tenantColumns,
    email: text("email").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    invitedBy: text("invited_by").notNull(),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    acceptedAt: text("accepted_at"),
    revokedAt: text("revoked_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("invitations_token_idx").on(table.tokenHash),
    index("invitations_org_email_idx").on(table.orgId, table.email),
  ],
);

export type MemberRow = typeof members.$inferSelect;
export type NewMemberRow = typeof members.$inferInsert;
export type InvitationRow = typeof invitations.$inferSelect;
 * statement is `IF NOT EXISTS`.
 */
export async function runMigrations(
  databasePath: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH,
): Promise<void> {
  const absolute = resolve(process.cwd(), databasePath);
  mkdirSync(dirname(absolute), { recursive: true });

  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");

  try {
    for (const statement of readMigrationStatements()) {
      sqlite.exec(statement);
    }
  } finally {
    sqlite.close();
  }
}

/** `pnpm db:migrate` runs this file directly; importing it must stay inert. */
if (process.argv[1]?.endsWith("migrate.ts") === true) {
  await runMigrations();
}

function readMigrationStatements(): readonly string[] {
  const dir = resolve(process.cwd(), MIGRATIONS_DIR);
  if (!existsSync(dir)) return SCHEMA_STATEMENTS;

  const files = readdirSync(dir)
    .filter((name) => name.endsWith(".sql"))
    .sort();

  if (files.length === 0) return SCHEMA_STATEMENTS;

  return files.flatMap((name) =>
    readFileSync(join(dir, name), "utf8")
      .split("--> statement-breakpoint")
      .map((chunk) => chunk.trim())
      .filter(Boolean),
  );
}
