const ISSUE_CREATE_RATE_BUCKET = "issue:create";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId, {
    includeArchived: true,
  });
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

/**
 * Imports a file as one authorized, quota-checked, rate-limited operation.
 * Persistence is atomic and the only announcement is the batch event.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const existing = issueImportRepo.findIssueImport(input.orgId, input.importKey);
  if (existing) {
    return {
      importKey: input.importKey,
      projectId: existing.projectId,
      issues: existing.issues,
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId, {
    includeArchived: true,
  });
  if (
    wouldExceedLimit(
      org.plan,
      "issuesPerProject",
      used,
      input.rows.length,
    )
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const emails = [
    ...new Set(
      input.rows.flatMap((row) =>
        row.assigneeEmail === null ? [] : [row.assigneeEmail.toLowerCase()],
      ),
    ),
  ];
  const assigneeIdsByEmail = await memberRepo.findActiveMemberUsersByEmail(
    input.orgId,
    emails,
  );

  setOrgPlan(input.orgId, org.plan);
  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_RATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const result = issueImportRepo.insertIssueImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    rows: input.rows,
    authorId: actor.userId,
    assigneeIdsByEmail,
  });

  if (result.replayed) return result;

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: result.projectId,
    importKey: result.importKey,
    issueIds: result.issues.map((issue) => issue.id),
  });

  return result;
}

