/**
 * A removed member is archived, never deleted, and no read ever surfaces one:
 * the scope is fixed here rather than threaded through every call site.
 */
const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};

function liveMemberPredicate() {
  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
}

export async function findMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

/** Resolves emails only through active, non-removed members of this workspace. */
export async function findActiveMemberUsersByEmail(
  orgId: OrgId,
  emails: readonly string[],
): Promise<ReadonlyMap<string, UserId>> {
  if (emails.length === 0) return new Map();

  const rows = getDb()
    .select({ email: users.email, userId: members.userId })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
        inArray(lower(users.email), emails.map((email) => email.toLowerCase())),
      ),
    )
    .all();

  return new Map(rows.map((row) => [row.email.toLowerCase(), row.userId as UserId]));
}

export async function findMemberById(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .get();
  return row ? toMember(row) : null;
}

